def esc(value):
    return html.escape(str(value), quote=True)

def arrow():
    return '<span aria-hidden="true">↗</span>'

def button(label, href, primary=False):
    return f'<a class="button{" primary" if primary else ""}" href="{href}">{label} {arrow()}</a>'

def eyebrow(text):
    return f'<p class="eyebrow">{text}</p>'

def section_head(number, title, intro=''):
    return f'<div class="section-heading"><p class="index">{number}</p><div><h2>{title}</h2>{"<p class=\"lede\">" + intro + "</p>" if intro else ""}</div></div>'

