mark = '<svg viewBox="0 0 36 36" aria-hidden="true"><path d="M4 8h11l6 6h11M4 18h28M4 28h11l6-6h11"/></svg>'

def header(current):
    nav = [('/#ecosystem','Four coins'),('/testnet.html','Testnet'),('/status.html','Progress'),('/break-it.html','Security')]
    def item(path, label):
        active = ' aria-current="page"' if path == current else ''
        return f'<a href="{path}"{active}>{label}</a>'
    return '<a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="header-inner"><a class="brand" href="/" aria-label="DAARX home">' + mark + '<span>DAARX<span class="brand-dot">.</span></span></a><nav class="desktop-nav" aria-label="Primary">' + ''.join(item(*x) for x in nav) + '</nav><details class="site-menu"><summary>Menu <span aria-hidden="true">＋</span></summary><nav aria-label="All pages">' + ''.join(item(c['path'], c['name']) for c in COINS) + ''.join(item(*x) for x in nav[1:]) + item('/mine.html','Hardware research') + item('/faq.html','FAQ') + item('/privacy.html','Privacy') + '</nav></details></div></header>'

def footer():
    return '<footer class="site-footer"><div class="container"><div class="footer-top"><a class="brand" href="/">' + mark + '<span>DAARX<span class="brand-dot">.</span></span></a><p>Four coins.<br>Built for different jobs.</p><button class="motion-toggle" type="button" data-motion aria-pressed="false">Pause motion <span aria-hidden="true">Ⅱ</span></button></div><div class="footer-links"><nav aria-label="Coins">' + ''.join(f'<a href="{c["path"]}">{c["name"]}</a>' for c in COINS) + '</nav><nav aria-label="Project"><a href="/testnet.html">Testnet</a><a href="/status.html">Development progress</a><a href="/break-it.html">Security</a><a href="/faq.html">FAQ</a></nav><nav aria-label="Site"><a href="/mine.html">Hardware research</a><a href="/flyer.html">Print flyer</a><a href="/privacy.html">Privacy</a><a href="mailto:daarxmoney@proton.me">Contact</a></nav></div><div class="footer-bottom"><p>Public Testnet preparation · reviewed ' + DATE + '</p><p>No coin sale. No public participation yet. Testnet coins will have no monetary value.</p><p>Site operator: Desiderata Labs LLC. DAARX is its registered alternate name. Protocol governance and commercial services are separate.</p></div></div></footer>'

def shell(path, title, description, body, extra_json=None, body_class=''):
    schema = {'@context':'https://schema.org','@type':'WebSite','name':'DAARX','url':ORIGIN,'description':'The four-coin DAARX system: DAARX, L10N, OPEN and Nexus / NXXXS. Public Testnet preparation.'}
    if extra_json: schema = extra_json
    return '<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#08090b"><title>' + esc(title) + '</title><meta name="description" content="' + esc(description) + '"><link rel="canonical" href="' + ORIGIN + path + '"><link rel="icon" href="/assets/mark.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/type.css"><link rel="stylesheet" href="/site.css"><meta property="og:type" content="website"><meta property="og:site_name" content="DAARX"><meta property="og:title" content="' + esc(title) + '"><meta property="og:description" content="' + esc(description) + '"><meta property="og:url" content="' + ORIGIN + path + '"><meta property="og:image" content="' + ORIGIN + '/og.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="' + esc(title) + '"><meta name="twitter:description" content="' + esc(description) + '"><meta name="twitter:image" content="' + ORIGIN + '/og.png"><script type="application/ld+json">' + json.dumps(schema, ensure_ascii=False).replace('</', r'<\/') + '</script><script src="/site.js" defer></script></head><body class="' + body_class + '">' + header(path) + '<main id="main">' + body + '</main>' + footer() + '</body></html>\n'

def intro(kicker, title, description, color='green', aside=''):
    return f'<section class="page-hero {color}"><div class="container"><a class="back-link" href="/">DAARX / {kicker}</a><div class="page-hero-grid"><div>{eyebrow(kicker)}<h1>{title}</h1><p class="hero-copy">{description}</p></div><div class="hero-aside">{aside}</div></div></div></section>'

def signal(label, value, cls=''):
    return f'<div class="signal {cls}"><span>{label}</span><strong>{value}</strong></div>'

def endnote(title, text, label='Follow the Testnet work', url='/status.html'):
    return f'<section class="endnote"><div class="container"><h2>{title}</h2><div><p>{text}</p>{button(label,url,True)}</div></div></section>'

def register(rows):
    return '<dl class="register">' + ''.join(f'<div><dt>{k}</dt><dd>{v}</dd></div>' for k,v in rows) + '</dl>'

def lens(name='SYSTEM / FOUR NATIVE COINS', coin='system'):
    return f'<div class="spectrum-lens" data-lens="{coin}"><canvas data-spectrum aria-hidden="true"></canvas><div class="lens-rings" aria-hidden="true"><i></i><i></i><i></i></div><div class="lens-label">{name}</div><div class="lens-center" aria-hidden="true"><span>4</span><small>NATIVE COINS</small></div><span class="orbit-label orbit-a">DAARX</span><span class="orbit-label orbit-b">L10N</span><span class="orbit-label orbit-c">OPEN</span><span class="orbit-label orbit-d">NXXXS</span><span class="lens-caption">Architecture study · not live network telemetry</span></div>'

def home():
    content = '<div class="update-strip"><div class="container"><span><i class="status-dot" aria-hidden="true"></i> Public Testnet preparation</span><a href="/status.html">' + SHORT_DATE + ' · See the work ' + arrow() + '</a></div></div>'
    content += '<section class="home-hero" id="top"><div class="container hero-grid"><div class="hero-word">' + eyebrow('DAARX / L10N / OPEN / NEXUS–NXXXS') + '<h1>Four coins.<br><em>Different jobs.</em></h1><p class="hero-copy">Private capital. Private cash. Accountable authority. Bonded assurance.</p><p class="hero-sub">Wallets, transfers, backups and recovery have been exercised in private builds. We’re preparing the four-coin public Testnet.</p><div class="actions">' + button('Meet the four coins','#ecosystem',True) + button('Where we are','/status.html') + '</div></div>' + lens() + '</div><div class="container hero-baseline"><span>PRIVATE INTEGRATION <b>Privately tested</b></span><span>PUBLIC RELEASE <b>In preparation</b></span><span>PUBLIC PARTICIPATION <b>Not open yet</b></span></div></section>'
    content += '<section class="section ecosystem" id="ecosystem"><div class="container"><span id="protocols" class="anchor-alias"></span>' + section_head('01','Keep. Spend.<br>Authorize. Verify.','Shared architecture does not mean interchangeable money. Each coin has its own state, rules and reason to exist.') + '<div class="coin-explorer" data-tabs><div class="coin-rail" role="tablist" aria-label="Explore the four coins">'
    for i,c in enumerate(COINS):
        content += f'<button class="coin-row {c["color"]}" id="coin-tab-{c["id"]}" type="button" role="tab" aria-selected="{"true" if i==0 else "false"}" aria-controls="coin-panel-{c["id"]}"><span class="coin-number">0{i+1}</span><span><strong>{c["name"]}</strong><small>{c["role"]}</small></span><span class="row-arrow" aria-hidden="true">↗</span></button>'
    content += '</div><div class="coin-panels">'
    for c in COINS:
        content += f'<div class="coin-panel {c["color"]}" id="coin-panel-{c["id"]}" role="tabpanel" aria-labelledby="coin-tab-{c["id"]}"><div class="coin-glyph {c["id"]}" aria-hidden="true"><i></i><i></i><i></i></div>{eyebrow(c["role"])}<h3>{c["short"]}</h3><p>{c["intro"]}</p><p class="small-copy">{c["detail"]}</p>{button("Explore " + c["name"],c["path"])}' + ('<p class="footnote">Nexus / NXXXS is the fourth coin’s working identity. Final public naming is still open.</p>' if c['id']=='nexus' else '') + '</div>'
    content += '</div></div></div></section>'
    content += '<section class="section architecture" id="thesis"><div class="container">' + section_head('02','Connected.<br>Still independent.','The architecture shares mining work. It keeps each coin’s native rules.') + '<div class="architecture-grid"><div class="chain-diagram" role="img" aria-label="RandomX parent work satisfies the DAARX target and carries L10N, OPEN and NXXXS child commitments. Each coin has independent native state and validity."><div class="parent-work"><span>SHARED PARENT WORK</span><strong>RandomX</strong><small>DAARX target + three child commitments</small></div><div class="chain-branches">' + ''.join(f'<div class="{c["color"]}"><span class="chain-dot" aria-hidden="true"></span><strong>{c["unit"]}</strong><small>Native state + rules</small></div>' for c in COINS) + '</div></div><div class="architecture-copy"><h3>Privacy for value.<br>Evidence for authority and work.</h3><p>DAARX and L10N target private value. OPEN makes authority, mandates and receipts inspectable. Nexus / NXXXS checks evidence and declared bonded commitments.</p><p>A valid payment on one chain does not become a payment on every chain. Ordinary DAARX, L10N and OPEN transfers do not require NXXXS or pay it an automatic share.</p><a class="text-link" href="/nexus.html">Read about the fourth coin ' + arrow() + '</a></div></div></div></section>'
    content += '<section class="section launch-section" id="status"><div class="container"><div class="launch-grid"><div>' + eyebrow('03 / THE NEXT RELEASE') + '<h2>Next stop:<br><em>public Testnet.</em></h2><p class="lede">The next release is the one other people will install, verify and recover.</p><p>We’re checking the current components and preparing the public source, network setup, signed builds and recovery instructions.</p>' + button('Read the readiness update','/status.html',True) + '</div><ol class="launch-list"><li><span class="step-state tested">PRIVATE EVIDENCE</span><h3>Protocols, wallets, recovery</h3><p>Real implementation and privately exercised integration paths.</p></li><li><span class="step-state active">CURRENT WORK</span><h3>Prepare the public release</h3><p>Exact configuration, builds, four-coin operation and participant recovery.</p></li><li><span class="step-state pending">NEXT PUBLIC MILESTONE</span><h3>Open participation</h3><p>Supported packages, verification instructions and public endpoints. Not open yet.</p></li></ol></div></div></section>'
    content += '<section class="section product-section"><div class="container">' + section_head('04','A system people can use.','Wallet and application work is moving alongside the protocols. Availability follows the release of each feature.') + '<div class="product-columns"><article><span class="small-index">01 / WALLETS</span><h3>A key needs a way home.</h3><p>Private work includes wallet creation, protected signing, reviewed transfers, pending journals, encrypted backups and recovery. A supported public wallet is part of participant delivery.</p></article><article><span class="small-index">02 / APPLICATIONS</span><h3>There’s life around the coins.</h3><p>Shared accounts, games, collectibles and Pride Pot components are in development. Game balances and rewards are separate from the four native coins. Public apps, funding and payment services still have work to finish.</p></article><article><span class="small-index">03 / FIRST TESTNET</span><h3>Start with what is supported.</h3><p>An online, valueless Testnet can open without a hardware store, completed offline cash, mobile-store launch or funded game rewards. Features need their own release evidence.</p></article></div></div></section>'
    content += endnote('Come for the idea.<br>Check the work.','Read what participation will involve, what is still being qualified and what will be published before entry opens.','About the Testnet','/testnet.html')
    return shell('/','DAARX — Four coins. Public Testnet is next.','DAARX, L10N, OPEN and Nexus / NXXXS: four native coins with distinct roles. Privately tested protocol, wallet and recovery work; public Testnet preparation.',content,body_class='home')

def coin_page(c):
    aside = f'<div class="coin-hero-symbol {c["color"]}"><div class="coin-glyph {c["id"]}" aria-hidden="true"><i></i><i></i><i></i></div><span>{c["unit"]}</span></div>'
    content = intro(c['role'], c['name'].replace(' / ','<br><span class="secondary-name">/ ') + ('</span>' if ' / ' in c['name'] else ''),c['intro'],c['color'],aside)
    content += '<div class="container"><div class="page-signal">' + signal('DEVELOPMENT',c['state']) + signal('PUBLIC NETWORK','Not open') + '</div></div>'
    content += '<section class="section" id="architecture"><div class="container">' + section_head('01',c['short'],c['detail']) + '<div class="inspection" data-tabs><div class="inspection-tabs" role="tablist" aria-label="' + esc(c['name']) + ' inspection">'
    for i,(name,title,text) in enumerate(c['tabs']):
        content += f'<button type="button" role="tab" id="inspect-{c["id"]}-{i}" aria-controls="inspect-panel-{c["id"]}-{i}" aria-selected="{"true" if i==0 else "false"}"><span>0{i+1}</span>{name}</button>'
    content += '</div><div class="inspection-panels">'
    for i,(name,title,text) in enumerate(c['tabs']):
        content += f'<div role="tabpanel" id="inspect-panel-{c["id"]}-{i}" aria-labelledby="inspect-{c["id"]}-{i}"><h3>{title}</h3><p>{text}</p></div>'
    content += '</div></div></div></section>'
    content += '<section class="section dim-section"><div class="container two-column"><div>' + eyebrow('02 / CURRENT DESIGN') + '<h2>The details<br>that matter.</h2><p>These describe the current work. Exact public parameters and release configuration still need to be qualified and published.</p></div>' + register(c['facts']) + '</div></section>'
    content += '<section class="section"><div class="container two-column"><div>' + eyebrow('03 / WALLET & RELEASE') + '<h2>Built privately.<br>Public work remains.</h2></div><div><h3>What exists</h3><p>' + c['wallet'] + '</p><h3>What it does not prove</h3><p>' + c['boundary'] + '</p><div class="actions">' + button('Current progress','/status.html') + button('Security','/break-it.html') + '</div></div></div></section>'
    content += '<section class="sibling-section"><div class="container"><p class="eyebrow">THE OTHER THREE</p><div class="sibling-grid">' + ''.join(f'<a class="sibling-link {x["color"]}" href="{x["path"]}"><span>{x["role"]}</span><strong>{x["name"]}</strong>{arrow()}</a>' for x in COINS if x['id'] != c['id']) + '</div></div></section>'
    return shell(c['path'],c['name'] + ' — ' + c['role'] + ' | DAARX',c['intro'],content,body_class=c['color'])

def status_page():
    content = intro('Development progress','Getting ready<br><em>for Testnet.</em>','The core protocols and wallets have been exercised privately. We’re checking the current components and preparing the source, network setup and packages for public participation.',aside=eyebrow('REVIEWED ' + SHORT_DATE) + '<p class="aside-statement">Private builds tested.<br>Public release in preparation.</p>')
    content += '<section class="section"><div class="container"><div class="status-explainer"><h2>Where we are.</h2><p>Protocol, wallet, history, packaging and recovery components have been built and exercised privately. The work now is to bring the current source, four-coin configuration, public builds and participant operations together.</p><p>This is a dated development update, not live telemetry or a completion percentage.</p></div><div class="readiness-register">'
    for num,title,state,cls,text in STATUS:
        content += f'<article class="readiness-row"><span class="index">{num}</span><div><h3>{title}</h3><p>{text}</p></div><span class="step-state {cls}">{state}</span></article>'
    content += '</div></div></section>'
    content += '<section class="section dim-section"><div class="container">' + section_head('02','The first Testnet<br>doesn’t need every future product.','An offered feature needs its own qualification. Keeping the first online release focused makes the boundaries understandable.') + '<div class="two-column"><div><h3>For supported online participation</h3><ul class="plain-list"><li>Exact source, network configuration and participant release.</li><li>Current correctness, four-chain operation and fault/recovery checks.</li><li>Reproducible builds, release verification and supported installation.</li><li>Bootstrap, test-coin access, observation and incident/reset guidance.</li></ul></div><div><h3>Separate feature releases</h3><ul class="plain-list"><li>Complete funded offline-cash and device/radio workflows.</li><li>Mobile-store releases, games and collectible products.</li><li>Live rewards, prizes, payment providers and redemption.</li><li>Hardware sales, hosting and paid support services.</li></ul></div></div></div></section>'
    content += '<section class="section"><div class="container two-column"><div>' + eyebrow('03 / AFTER PUBLIC ENTRY') + '<h2>Testnet is a test.<br>Mainnet is another release.</h2></div><div><p>Public participation is meant to produce evidence: real network behavior, defects, operator experience and recovery under stress. It does not turn test coins into money or certify the system for real funds.</p><p>Public entry requires the review and safety evidence applicable to that release. Independent professional audit, broader public-network evidence and separate mainnet testing remain outstanding. There is no fixed launch countdown.</p>' + button('Read the security boundaries','/break-it.html') + '</div></div></section>'
    return shell('/status.html','Development progress — DAARX public Testnet preparation','Current four-coin development status: private implementation evidence, release qualification, network configuration, public builds and participation work.',content)

def testnet_page():
    content = intro('Public Testnet','Bring curiosity.<br><em>Leave real funds out.</em>','The first public Testnet will be a place to run the software, find faults and help test recovery. Entry is not open yet.',aside=signal('CURRENT STAGE','Public Testnet preparation')+signal('PARTICIPATION','Not open')+signal('TEST COINS','No monetary value'))
    content += '<section class="section"><div class="container">' + section_head('01','What you’ll be able to test.','The supported release will define exactly which platforms, chains and features are available. No participant package is published here yet.') + '<div class="product-columns"><article><span class="small-index">RUN</span><h3>A node or miner.</h3><p>Verify a release, join the published network configuration, and test the supported mining and transaction paths. Hardware and operating-system support will be stated in the release.</p></article><article><span class="small-index">USE</span><h3>A test wallet.</h3><p>Create a separate wallet, receive valueless test coins, send transactions and exercise the supported backup and recovery flow. A test balance is not a mainnet allocation.</p></article><article><span class="small-index">BREAK & REPORT</span><h3>Find the rough edges.</h3><p>Record reproducible failures within the published test scope. Public Testnet participation and a paid security bounty are different programs.</p></article></div></div></section>'
    content += '<section class="section dim-section"><div class="container two-column"><div>' + eyebrow('02 / BEFORE ENTRY OPENS') + '<h2>You should have<br>the whole starting kit.</h2></div><ol class="numbered-list"><li><strong>Verify what you download.</strong><p>Exact version, supported source, hashes, signatures and build instructions.</p></li><li><strong>Know which network you are joining.</strong><p>Configuration, bootstrap peers, test-coin access and observation tools.</p></li><li><strong>Know how to recover.</strong><p>Wallet backup, installation, restart, incident and reset instructions.</p></li><li><strong>Know where reports go.</strong><p>Published scope, reporting route, known issues and support boundaries.</p></li></ol></div></section>'
    content += '<section class="section"><div class="container two-column"><div>' + eyebrow('03 / EXPECTATIONS') + '<h2>Things will break.<br>That’s why we test.</h2></div><div><p>Test networks can reset. Software can lose state, fail or change format. Use separate test wallets and never put an existing seed, mainnet key, real funds or sensitive personal data into a test workflow.</p><p>Offline cash, games, mobile apps, hardware and reward programs will only be included when separately supported. Their existence in development is not a public availability claim.</p><p>There is no Testnet signup form on this page. Hardware interest is kept separate.</p><div class="actions">' + button('See remaining release work','/status.html',True)+button('Questions and answers','/faq.html') + '</div></div></div></section>'
    return shell('/testnet.html','Public Testnet — participation and preparation | DAARX','What the DAARX four-coin public Testnet will involve, what must be published before entry opens, and why test coins have no monetary value.',content)

def security_page():
    content = intro('Security','Check the claims.<br><em>Then check the code.</em>','Private tests are useful evidence. They do not replace independent review, a public network campaign or scrutiny of the system as a whole.',aside=signal('PROFESSIONAL AUDIT','Not complete')+signal('PUBLIC BOUNTY','Not open'))
    content += '<section class="section" id="more"><div class="container">' + section_head('01','The review has to reach<br>the whole system.','Reviewed dependencies do not automatically make their composition safe.') + '<div class="product-columns"><article><h3>Cryptography.</h3><p>Proof systems, amount commitments, signatures and their dependencies need scrutiny of assumptions, implementation and integration.</p></article><article><h3>Consensus and the network.</h3><p>Transaction rules, mining commitments, history, forks, cross-chain boundaries and fault behavior must agree in the actual release.</p></article><article><h3>The person holding the key.</h3><p>Wallet creation, signing, backups, interrupted sends, recovery and device behavior are part of the security boundary.</p></article></div></div></section>'
    content += '<section class="section dim-section" id="security-network"><div class="container two-column"><div>' + eyebrow('02 / PUBLIC TESTING') + '<h2>A network campaign<br>has a different job.</h2></div><div><p>The public Testnet is intended to exercise software and operations beyond controlled private tests. Supported participation, reset rules, report scope and recovery instructions will be published with the release.</p><p>Public entry is not open yet. This page does not authorize testing third-party services, commercial infrastructure or systems outside a published scope.</p>' + button('About public participation','/testnet.html') + '</div></div></section>'
    content += '<section class="section" id="security-bounty"><div class="container two-column"><div>' + eyebrow('03 / SECURITY PROGRAM') + '<h2>The public program<br>hasn’t opened.</h2></div><div><p>A public program needs confirmed funding, official rules, clear scope, a reporting channel, safe-harbor terms, response expectations and an award process. Those are not published as an active offer today.</p><p>No amount, reward, credit or invitation is promised by this page. A hardware-interest submission does not enter a security program.</p></div></div></section>'
    content += '<section class="section dim-section" id="security-report"><div class="container two-column"><div>' + eyebrow('04 / CONTACT') + '<h2>Questions are welcome.</h2></div><div><p>For general project questions, contact <a href="mailto:daarxmoney@proton.me">daarxmoney@proton.me</a>. A dedicated vulnerability intake and its encryption instructions must be published before a public security program opens.</p><p>Do not email wallet seeds, private keys, credentials or someone else’s personal data.</p></div></div></section>'
    return shell('/break-it.html','Security and review — DAARX','DAARX security boundaries, private test evidence, independent review and the planned public security program. No public bounty is open.',content)

def faq_page():
    body = intro('Questions & answers','Fair questions.<br><em>Straight answers.</em>','The four coins, the current release work, what you can use today, and what still has to happen.')
    body += '<section class="section" id="questions"><div class="container faq-layout"><div class="faq-sidebar"><label for="faq-query">Find an answer</label><input type="search" id="faq-query" placeholder="Try “wallet”, “four coins” or “mining”" autocomplete="off" aria-describedby="faq-results"><output id="faq-results" for="faq-query" aria-live="polite">' + str(len(FAQ)) + ' answers</output><p>Still wondering?</p><a class="text-link" href="mailto:daarxmoney@proton.me">Email a person ' + arrow() + '</a></div><div class="faq-list">'
    for i,(q,a) in enumerate(FAQ):
        body += f'<details class="qa"{" open" if i==0 else ""}><summary>{esc(q)}<span aria-hidden="true">＋</span></summary><div><p>{esc(a)}</p></div></details>'
    body += '<p class="no-results" hidden>No matching answers. Try a shorter word, or clear the search.</p></div></div></section>'
    schema={'@context':'https://schema.org','@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in FAQ]}
    return shell('/faq.html','Questions and answers — DAARX four-coin system','Direct answers about DAARX, L10N, OPEN, Nexus / NXXXS, public Testnet preparation, wallets, mining, privacy and hardware interest.',body,schema)

def privacy_page():
    body = intro('Privacy notice','Know what leaves<br><em>your browser.</em>','This notice covers the information site and its optional hardware-interest form. Reviewed ' + DATE + '.',aside='<div class="data-path"><span>Browser</span><i aria-hidden="true">↓</i><span>GitHub Pages</span><i aria-hidden="true">↓ only if you submit interest</i><span>Web3Forms → Proton → Labs</span></div>')
    cards=[('Operator','Desiderata Labs LLC operates this DAARX-branded information site and the hardware-interest form. DAARX is its registered alternate name. Protocol governance and commercial services are separate. No store, checkout, account or paid support service is offered on this site.'),('Browsing','The public pages use no advertising trackers, analytics scripts, accounts or marketing cookies. Fonts and visual effects are served with the site. The motion control changes only the current page; it does not store a preference. GitHub Pages may process ordinary network, device, delivery, security and server-log metadata.'),('What the form sends','Your email address; optional name or handle; selected hardware concept; access-model, membership, hosting, accessory and merchandise interests; optional notes; your privacy-notice acknowledgment; and delivery metadata. Do not enter secrets, payment-card data, identity documents, wallet keys or recovery phrases.'),('Purpose','To record and manage non-binding hardware interest, answer questions, prevent abuse and contact you if a relevant compliant offer or material update becomes available. A submission does not create an order, account, financing application or protocol allocation. We do not sell personal information or make automated eligibility decisions.'),('Providers','GitHub Pages hosts the site. Web3Forms processes and relays the form. Proton receives the message. These independent providers may process network, device, delivery, anti-abuse and log metadata under their own terms and notices. We disclose information to operate the site and form, respond to you, protect the service or comply with law.'),('Retention','An active interest record is kept only as long as needed to manage the pre-launch list and follow up, and no longer than 24 months after your last interaction unless a shorter legal or operational period applies. Provider copies, backups and logs follow provider retention and may not be immediately removable by us. Deletion from records we control is completed within 30 days unless preservation is legally required.'),('Your control','Submitting interest is optional, non-binding and free. Ask to access, correct or delete a record, or withdraw from follow-up, at daarxmoney@proton.me. We may ask you to verify control of the email address before changing or deleting a record.'),('Children and security','The form is not directed to children; minors should not submit it. Internet transmission and email cannot be guaranteed perfectly secure. Access is limited to the people and providers needed to operate the form and follow up. No payment data is requested.'),('Future changes','A future store, checkout, account, support or analytics feature needs an updated notice before its processing starts. This notice describes the current static site and hardware-interest relay.')]
    body += '<section class="section" id="data-register"><div class="container privacy-register">' + ''.join(f'<article><h2>{h}</h2><p>{t}</p></article>' for h,t in cards) + '<p>' + button('Ask about your data','mailto:daarxmoney@proton.me') + '</p></div></section>'
    return shell('/privacy.html','Privacy notice — DAARX','How Desiderata Labs LLC handles browsing and optional hardware-interest information, including providers, retention and deletion requests.',body)

HARDWARE=[('node','Node Box','299','Node-only concept','No mining claim'),('compact','Mini Miner','699','Compact miner/node','6–8 kH/s estimate'),('compact','Beefy Mini','1,399','16-core compact concept','16–20 kH/s estimate'),('rig','Standard','1,899','Ryzen 9 5900XT concept','20 kH/s estimate'),('rig','Pro','2,499','Ryzen 9 9950X concept','27 kH/s estimate'),('rig','Pro ACE','2,899','Ryzen 9 9950X3D concept','27 kH/s estimate'),('rig','Pro ACE II','3,299','Dual-CCD 3D-cache placeholder','27 kH/s estimate'),('scale','BIG_DOG','7,499','32-core Threadripper concept','40 kH/s estimate'),('scale','BIG_DOG MAX','10,999','64-core Threadripper concept','84 kH/s estimate')]

def hardware_page(original_form):
    body=intro('Hardware research','Software first.<br><em>Hardware studies follow.</em>','These are engineering and demand studies, not products for sale. No supported public mining package, checkout, inventory hold or shipping promise exists.',aside=signal('HARDWARE SALES','Not open')+signal('FIGURES BELOW','Unverified planning estimates'))
    body+='<section class="section" id="concepts"><div class="container">'+section_head('01','Choose a scale.','Prices, hashrates, components, power, noise, support and delivery are not verified. Do not buy equipment based on these figures.')+'<div class="hardware-tabs" data-tabs><div class="inspection-tabs" role="tablist" aria-label="Hardware concept scale">'
    for i,(k,label) in enumerate([('node','Node'),('compact','Compact'),('rig','Rig'),('scale','BIG_DOG')]):
        body+=f'<button type="button" role="tab" id="tab-{k}" aria-controls="panel-{k}" aria-selected="{"true" if i==0 else "false"}">{label}</button>'
    body+='</div>'
    for key in ['node','compact','rig','scale']:
        body+=f'<div role="tabpanel" id="panel-{key}" aria-labelledby="tab-{key}" class="hardware-panel">'
        for kind,name,price,description,estimate in HARDWARE:
            if kind!=key:continue
            choice=(name+' (32-core)' if name=='BIG_DOG' else name+' (64-core)' if name=='BIG_DOG MAX' else name)+' — est. $'+price
            body+=f'<a class="hardware-row" href="#reserve" data-sku="{esc(choice)}"><div><h3>{name}</h3><p>{description}</p></div><span>{estimate}</span><strong>est. ${price}</strong><span aria-hidden="true">↗</span></a>'
        body+='</div>'
    body+='</div><p class="footnote">The Pro ACE studies do not have a verified mining advantage over Pro. Any premium silicon would be for other workloads. Node Box is not a mining or earnings concept.</p></div></section>'
    body+='<section class="section dim-section" id="self-build"><div class="container two-column"><div>'+eyebrow('02 / BUILD YOUR OWN')+'<h2>No hardware purchase<br>should be required.</h2><p>A free release image and a vetted parts list are intended. Signed images, compatibility tests, secure updates and support boundaries are not released yet.</p></div>'+register([('CPU study','Ryzen 9 5900XT · 16 cores'),('Board / memory','B550 ATX (AM4) / 16 GB dual-channel DDR4'),('Power supply','650W Gold-class concept; not a wall-power estimate'),('Display / storage','Intel Arc A310 / NVMe SSD'),('Cooling','Air cooling · validation pending')])+'</div></section>'
    body+='<section class="section"><div class="container">'+section_head('03','Other ideas under study.','None of these access models, memberships or accessories is currently offered.')+'<div class="product-columns"><article><h3>Access models.</h3><p>Possible purchase, hosted ownership and rental. Financing, title, custody, power, downtime, taxes, cancellation and support terms remain unresolved.</p></article><article><h3>Possible memberships.</h3><p>Managed support (~$25/month), hosting (~$75/month) and community (~$20/month) are unverified demand estimates, not subscriptions available to buy.</p></article><article><h3>Accessories & merch.</h3><p>Possible status display ($79), backup plate ($49), release USB ($29), merch (from $28) and a Proof-of-Squish three-pack. Design, validation and terms remain open.</p></article></div><div class="accessory-links">'+''.join(f'<a href="#reserve" data-acc="{key}">{label} {arrow()}</a>' for key,label in [('acc_display','Status display'),('acc_coldstorage','Backup plate'),('acc_usb','Release USB'),('acc_merch','Merch'),('acc_squish','Squish three-pack')])+'</div></div></section>'
    form=original_form.replace('TRANSMIT INTEREST SIGNAL','Send hardware interest').replace('placeholder="Satoshi"','placeholder="Your name or handle"')
    body+='<section class="section dim-section" id="reserve"><div class="container two-column"><div>'+eyebrow('04 / OPTIONAL HARDWARE INTEREST')+'<h2>Tell us what<br>you’d consider.</h2><p>This form is for hardware research. It is not a Testnet signup, order, quote, priority reservation or financing application.</p><p>Desiderata Labs LLC operates this form. Submission is free. See the <a href="/privacy.html">privacy notice</a> for the relay, retention and deletion details.</p></div><div class="form-wrap">'+form+'<p id="f-status" role="status" aria-live="polite" tabindex="-1"></p></div></div></section>'
    return shell('/mine.html','Hardware research — DAARX','Unverified hardware concepts and optional non-binding interest. No sale, supported public miner, reservation, financing or shipping promise.',body)

def flyer_page():
    old=(ROOT/'flyer.html').read_text()
    qr=re.search(r'<svg[^>]*class="segno"[\s\S]*?</svg>',old)
    if not qr:raise ValueError('Original QR graphic missing')
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>DAARX four-coin flyer</title><link rel="stylesheet" href="/assets/type.css"><link rel="stylesheet" href="/print.css"><script src="/print.js" defer></script></head><body><header class="print-toolbar"><a href="/">← DAARX</a><span>Paper <button type="button" data-paper="letter" aria-pressed="true">Letter</button><button type="button" data-paper="a4" aria-pressed="false">A4</button></span><button type="button" data-print>Print flyer ↗</button></header><main class="print-sheet"><p class="print-eyebrow">DAARX / L10N / OPEN / NEXUS–NXXXS</p><h1>Four coins.<br>Different jobs.</h1><p class="print-lede">Private money. Accountable authority.<br>A public Testnet on the way.</p><div class="print-coins">' + ''.join(f'<section><h2>{c["name"]}</h2><p>{c["role"]}</p><p>{c["intro"]}</p></section>' for c in COINS) + '</div><p>Protocol, wallet and recovery components have private implementation and testing evidence. The exact public release, network configuration, builds and participant operations are being qualified.</p><p>Public entry is not open. No coin sale. No hardware sale.<br>Testnet coins will have no monetary value.<br>Nexus / NXXXS is the fourth coin’s working identity.</p><div class="print-bottom"><div class="qr">'+qr.group(0)+'</div><div><strong>daarx.money</strong><p>Current progress, the four coins,<br>and what Testnet participation will involve.</p><small>Reviewed '+DATE+'</small></div></div></main></body></html>\n'

def main():
    original=(ROOT/'mine.html').read_text()
    form=re.search(r'<form\b[^>]*class="pre"[\s\S]*?</form>',original)
    if not form:raise ValueError('Existing hardware form not found; never replace its endpoint or access key implicitly')
    fonts=re.findall(r'@font-face\{[^}]+\}',(ROOT/'style.css').read_text())
    (ROOT/'assets/type.css').write_text('\n'.join(fonts)+'\n')
    (ROOT/'assets/mark.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 36 36"><rect width="36" height="36" rx="8" fill="#08090b"/><path d="M4 8h11l6 6h11M4 18h28M4 28h11l6-6h11" fill="none" stroke="#83f6b1" stroke-width="2"/></svg>\n')
    pages={'index.html':home(),'status.html':status_page(),'testnet.html':testnet_page(),'break-it.html':security_page(),'faq.html':faq_page(),'privacy.html':privacy_page(),'mine.html':hardware_page(form.group(0)),'flyer.html':flyer_page()}
    for c in COINS:pages[c['path'].lstrip('/')]=coin_page(c)
    for name,source in pages.items():
        source = source.replace('<!doctype html>', '<!DOCTYPE html>')
        source = re.sub(r'&(?![A-Za-z][A-Za-z0-9]+;|#[0-9]+;|#x[0-9A-Fa-f]+;)', '&amp;', source)
        source = source.replace('><', '>\n<')
        (ROOT/name).write_text(source)
    urls=['/']+['/'+name for name in pages if name not in ['index.html','flyer.html']]
    (ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'  <url><loc>{ORIGIN}{p}</loc><lastmod>2026-11-04</lastmod></url>\n' for p in urls)+'</urlset>\n')
    (ROOT/'data').mkdir(exist_ok=True)
    (ROOT/'data/release-status.json').write_text(json.dumps({'as_of':'2026-11-04','stage':'Public Testnet preparation','public_participation_open':False,'native_coin_count':4,'coins':[{'name':c['name'],'unit':c['unit'],'role':c['role'],'working_identity':c['id']=='nexus'} for c in COINS],'work':[{'area':title,'state':state,'description':text} for num,title,state,cls,text in STATUS],'independent_professional_audit_complete':False,'hardware_sales_open':False,'test_coins_have_monetary_value':False},indent=2,ensure_ascii=False)+'\n')
    print(f'Generated {len(pages)} pages; one existing hardware form retained; {len(urls)} sitemap entries.')

if __name__=='__main__':main()
